parameters.query:
SELECT geocode, nome, pop FROM municipio
WHERE unaccent(lower(nome)) LIKE unaccent(lower('%' || $1 || '%'))
ORDER BY length(nome) LIMIT 5;

SELECT doenca, se, data_inise, casos, round(casos_est) AS casos_estimados,
       nivel, round(rt, 2) AS rt, round(p_inc100k, 1) AS incidencia_100k
FROM situacao_atual WHERE geocode = $1::bigint ORDER BY doenca;

SELECT nome, se, nivel, round(casos_est) AS casos_estimados, round(rt, 2) AS rt
FROM situacao_atual WHERE doenca = $1
ORDER BY nivel DESC, casos_est DESC NULLS LAST LIMIT 10;
